// ===== WIP16A: PHALANX FIRE-CONTROL STABILIZATION =====
// The stable v48 implementation allowed gunfire with several degrees of residual mount error.
// At CIWS range that can put the centre of the physical Mk244 dispersion group metres away
// from a missile even when the local RF track itself is excellent. WIP16A therefore gates
// rounds on a range-scaled burst-centre error budget while preserving fixed ammunition
// dispersion and the existing sensor/ballistic solution.
const WIP16_PHALANX_FIRE_CONTROL_MODEL=Object.freeze({
  schema:'PHALANX_FIRE_CONTROL_STABILIZATION_V48_1_WIP16A',
  groupRadiusFractionForCenterGate:.32,
  baseCenterGateM:.42,
  minCenterGateM:.55,
  maxCenterGateM:2.10,
  predictedMissBaseM:.50,
  predictedMissGroupFraction:.18,
  engageHysteresis:1.35,
});
function phalanxFireControlGate(mount,st,sol,turretErr,engaged=false){
  const M=WIP16_PHALANX_FIRE_CONTROL_MODEL,rangeM=Math.max(1,Number(st?.rangeM)||Math.hypot(st?.rxM??0,st?.ryM??0,st?.rzM??0)||1);
  const group80RadiusM=rangeM*PHALANX_MK244_BALLISTICS.dispersion80DiameterMil*.0005;
  const centerGateM=clamp(M.baseCenterGateM+group80RadiusM*M.groupRadiusFractionForCenterGate,M.minCenterGateM,M.maxCenterGateM)*(engaged?M.engageHysteresis:1);
  const turretCenterErrorM=Math.tan(Math.min(deg(20),Math.abs(Number(turretErr)||0)))*rangeM;
  const predictedMissM=Math.max(0,Number(sol?.predictedMissM)||0),predictedMissLimitM=(M.predictedMissBaseM+group80RadiusM*M.predictedMissGroupFraction)*(engaged?M.engageHysteresis:1);
  return {ready:!!sol&&turretCenterErrorM<=centerGateM&&predictedMissM<=predictedMissLimitM,rangeM,group80RadiusM,centerGateM,turretCenterErrorM,predictedMissM,predictedMissLimitM};
}
window.__WIP16_PHALANX_FC__={profile:()=>({...WIP16_PHALANX_FIRE_CONTROL_MODEL}),gate:(rangeM,turretErrDeg,predictedMissM=0,engaged=false)=>phalanxFireControlGate(null,{rangeM},{predictedMissM},deg(turretErrDeg),engaged)};

